// testAccWaitSeededRegistrationPending waits for the freshly-seeded
// registration to transition into PENDING.
func testAccWaitSeededRegistrationPending(t *testing.T, apiClient *client.APIClient, fixture *testRegistrationFixture) {
	t.Helper()

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
	defer cancel()

	findByState := func(state ves_io_schema_registration.ObjectState) *ves_io_schema_registration.ListResponseItem {
		listReq := &ves_io_schema_registration.ListStateReq{
			Namespace: fixture.namespace,
			State:     state,
		}

		yamlReq, err := codec.ToYAML(listReq)
		if err != nil {
			return nil
		}

		listRespMsg, err := apiClient.CustomAPI(
			ctx,
			http.MethodPost,
			fmt.Sprintf(regTestListByStateURI, fixture.namespace),
			regTestListByStateRPCFQN,
			yamlReq,
		)
		if err != nil {
			return nil
		}

		listResp, ok := listRespMsg.(*ves_io_schema_registration.ListResponse)
		if !ok {
			return nil
		}

		for _, item := range listResp.GetItems() {
			if item == nil {
				continue
			}

			itemCluster := item.GetGetSpec().GetPassport().GetClusterName()
			if itemCluster == "" {
				itemCluster = item.GetObject().GetSpec().GetGcSpec().GetPassport().GetClusterName()
			}

			itemHostname := item.GetGetSpec().GetInfra().GetHostname()
			if itemHostname == "" {
				itemHostname = item.GetObject().GetSpec().GetGcSpec().GetInfra().GetHostname()
			}

			if strings.EqualFold(itemCluster, fixture.clusterName) && strings.EqualFold(itemHostname, fixture.hostname) {
				return item
			}
		}

		return nil
	}

	for {
		item := findByState(ves_io_schema_registration.PENDING)
		if item != nil {
			regName := strings.TrimSpace(item.GetName())
			if regName == "" {
				regName = strings.TrimSpace(item.GetMetadata().GetName())
			}
			if regName != "" {
				return
			}
		}

		select {
		case <-ctx.Done():
			t.Fatalf("testAccWaitSeededRegistrationPending: matching registration did not become PENDING for cluster=%s hostname=%s before timeout", fixture.clusterName, fixture.hostname)
		case <-time.After(20 * time.Second):
		}
	}
}

func testAccRegistrationStateCheck(resourceAddr string, apiClient *client.APIClient, expectedState ves_io_schema_registration.ObjectState) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		namespace, registrationName, err := testAccStateNamespaceAndRegistrationName(s, resourceAddr)
		if err != nil {
			return err
		}

		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
		defer cancel()

		listReq := &ves_io_schema_registration.ListStateReq{
			Namespace: namespace,
			State:     expectedState,
		}

		yamlReq, err := codec.ToYAML(listReq)
		if err != nil {
			return fmt.Errorf("testAccRegistrationStateCheck: marshal failed: %w", err)
		}

		listRespMsg, err := apiClient.CustomAPI(
			ctx,
			http.MethodPost,
			fmt.Sprintf(regTestListByStateURI, namespace),
			regTestListByStateRPCFQN,
			yamlReq,
		)
		if err != nil {
			return fmt.Errorf("testAccRegistrationStateCheck: list API failed: %w", err)
		}

		listResp, ok := listRespMsg.(*ves_io_schema_registration.ListResponse)
		if !ok {
			return fmt.Errorf("testAccRegistrationStateCheck: unexpected list response type %T", listRespMsg)
		}

		for _, item := range listResp.GetItems() {
			if item == nil {
				continue
			}

			itemName := strings.TrimSpace(item.GetName())
			if itemName == "" {
				itemName = strings.TrimSpace(item.GetMetadata().GetName())
			}

			if itemName == registrationName {
				return nil
			}
		}

		return fmt.Errorf("testAccRegistrationStateCheck: registration %q not found in namespace %q with state %q", registrationName, namespace, expectedState.String())
	}
}

func testAccStateNamespaceAndRegistrationName(s *terraform.State, resourceAddr string) (string, string, error) {
	for _, mod := range s.Modules {
		for addr, rs := range mod.Resources {
			if addr != resourceAddr {
				continue
			}
			if rs.Primary == nil {
				return "", "", fmt.Errorf("resource %s has no primary instance", resourceAddr)
			}

			namespace := strings.TrimSpace(rs.Primary.Attributes["namespace"])
			registrationName := strings.TrimSpace(rs.Primary.Attributes["registration_name"])
			if namespace == "" {
				namespace = "system"
			}
			if registrationName == "" {
				return "", "", fmt.Errorf("resource %s has no registration_name in state", resourceAddr)
			}

			return namespace, registrationName, nil
		}
	}

	return "", "", fmt.Errorf("resource %s not found in state", resourceAddr)
}

// testAccCleanupRegistration retires the seeded registration and deletes the token.
func testAccCleanupRegistration(t *testing.T, apiClient *client.APIClient, fixture *testRegistrationFixture) {
	t.Helper()

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()

	for _, state := range []ves_io_schema_registration.ObjectState{
		ves_io_schema_registration.NEW,
		ves_io_schema_registration.PENDING,
		ves_io_schema_registration.APPROVED,
	} {
		listReq := &ves_io_schema_registration.ListStateReq{
			Namespace: fixture.namespace,
			State:     state,
		}
		yamlReq, err := codec.ToYAML(listReq)
		if err != nil {
			continue
		}

		listRespMsg, err := apiClient.CustomAPI(ctx, http.MethodPost,
			fmt.Sprintf(regTestListByStateURI, fixture.namespace),
			regTestListByStateRPCFQN, yamlReq)
		if err != nil {
			continue
		}
		listResp, ok := listRespMsg.(*ves_io_schema_registration.ListResponse)
		if !ok {
			continue
		}

		for _, item := range listResp.GetItems() {
			if item == nil {
				continue
			}
			itemCluster := item.GetGetSpec().GetPassport().GetClusterName()
			if itemCluster == "" {
				itemCluster = item.GetObject().GetSpec().GetGcSpec().GetPassport().GetClusterName()
			}
			itemHostname := item.GetGetSpec().GetInfra().GetHostname()
			if itemHostname == "" {
				itemHostname = item.GetObject().GetSpec().GetGcSpec().GetInfra().GetHostname()
			}
			if !strings.EqualFold(itemCluster, fixture.clusterName) || !strings.EqualFold(itemHostname, fixture.hostname) {
				continue
			}

			regName := strings.TrimSpace(item.GetName())
			if regName == "" {
				regName = strings.TrimSpace(item.GetMetadata().GetName())
			}
			if regName == "" {
				continue
			}

			passport := item.GetGetSpec().GetPassport()
			if passport == nil {
				passport = item.GetObject().GetSpec().GetGcSpec().GetPassport()
			}
			if passport == nil {
				passport = &ves_io_schema_registration.Passport{ClusterName: fixture.clusterName, ClusterSize: 1}
			}

			retireReq := &ves_io_schema_registration.ApprovalReq{
				Namespace: fixture.namespace,
				Name:      regName,
				State:     ves_io_schema_registration.RETIRED,
				Passport:  passport,
			}
			yamlRetire, err := codec.ToYAML(retireReq)
			if err != nil {
				continue
			}
			_, _ = apiClient.CustomAPI(ctx, http.MethodPost,
				fmt.Sprintf(regTestApproveURI, fixture.namespace, regName),
				regTestApproveRPCFQN, yamlRetire)
			t.Logf("testAccCleanupRegistration: retired %s", regName)
		}
	}

	testAccDeleteTokenViaAPI(t, apiClient, fixture.namespace, fixture.tokenName)
}

// testAccRegistrationApprovalImportStateID returns the import ID in the
// format "namespace/registration_name" (not "namespace/name").
func testAccRegistrationApprovalImportStateID(resourceAddr string) func(*terraform.State) (string, error) {
	return func(s *terraform.State) (string, error) {
		namespace, registrationName, err := testAccStateNamespaceAndRegistrationName(s, resourceAddr)
		if err != nil {
			return "", err
		}

		return namespace + "/" + registrationName, nil
	}
}

